INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'au-anz-arrangement-2018', id, '2018-01-01', 1, 'https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing' FROM countries WHERE name_en = 'Australia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-anz-arrangement-2018', 'en', 'Australia–New Zealand Government Electronic Invoicing Arrangement', 'Both governments agree a common approach to e-invoicing — the foundation for the shared PINT A-NZ specification both countries use today.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'au-ncereceive', id, '2022-07-01', 1, 'https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing' FROM countries WHERE name_en = 'Australia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-ncereceive', 'en', 'Federal agencies mandatory to receive Peppol e-invoices (in force since Jul 2022)', 'All Non-Corporate Commonwealth Entities (federal agencies) have been required to receive Peppol e-invoices since 1 July 2022. There is no general B2B mandate, but government adoption continues to accelerate.', '["Suppliers to federal agencies: connect via an ATO-accredited Peppol Access Point", "Invoices delivered via Peppol may be paid within 5 days rather than the standard 20"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'au-pint-mandatory-2024', id, '2024-11-15', 1, 'https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing' FROM countries WHERE name_en = 'Australia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-pint-mandatory-2024', 'en', 'PINT A-NZ becomes mandatory', 'The updated Peppol International specification for Australia and New Zealand supersedes the earlier A-NZ Peppol BIS Billing extension.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'au-legacy-removed-2025', id, '2025-05-15', 1, 'https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing' FROM countries WHERE name_en = 'Australia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-legacy-removed-2025', 'en', 'Legacy specifications fully removed', 'All users must exchange PINT A-NZ — it becomes the only supported specification for sending and receiving invoices and credit notes on the network.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'au-default-2025', id, '2025-07-01', 1, 'https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing' FROM countries WHERE name_en = 'Australia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-default-2025', 'en', 'ATO establishes e-invoicing as the default for NCEs', 'The Australian Taxation Office announces that e-invoicing becomes the default invoice exchange method for Non-Corporate Commonwealth Entities, as part of a broader strategy to cut administrative overhead and speed up payment cycles.', '[]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'au-30pct', id, '2026-07-01', 0, 'https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing' FROM countries WHERE name_en = 'Australia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-30pct', 'en', '30% of federal agency invoices must be processed via Peppol', 'Non-Corporate Commonwealth Entities must have at least 30% of received supplier invoices flowing through the Peppol network, en route to full automation by December 2026.', '["If you supply Australian federal agencies, confirm your invoicing is Peppol-enabled", "Use the PINT A-NZ format — the only supported standard since 15 May 2025"]');
INSERT INTO milestones (id, country_id, date, anchor, source_url) SELECT 'au-automate', id, '2026-12-01', 0, 'https://www.ato.gov.au/businesses-and-organisations/einvoicing/what-is-einvoicing' FROM countries WHERE name_en = 'Australia';
INSERT INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('au-automate', 'en', 'Federal agencies must automate e-invoice sending and processing', 'Non-Corporate Commonwealth Entities must be able to automatically process received e-invoices and send e-invoices, with quarterly progress reporting to the Australian Peppol Authority.', '["Confirm your e-invoicing setup supports fully automated, touchless processing", "Government suppliers should expect faster payment cycles as automation lands"]');
